import React from "react";
import { Link } from "react-router-dom";

export default function HomePage() {
   const navigate = useNavigate();
    const token = localStorage.getItem("token");
  
    const startCoding = () => {
      if (token) {
        navigate("/editor");
      } else {
        navigate("/login");
      }
    };
  
  return (
    <section>
      <h1>Welcome to DailyCode</h1>

      <Link to="/editor">
        Start Coding
      </Link>
    </section>
  );
}
